import{selectCohortPopulation}from'./cohort-049-meta.js';
import{cohortDistribution}from'./cohort-features.js';
export function csvCell(value){let s=value==null?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[\s]*[=+@-]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';}
export function cohortCSV(rows,{kind='distribution',group='all',cohort='all'}={}){rows=selectCohortPopulation(rows,cohort);let table;if(kind==='profiles'){const keys=[...new Set(rows.flatMap(r=>Object.keys(r.biography)))];table=[['ID','Cohort','Classification',...keys.map(k=>'Biography · '+k),'R','I','A','S','E','C','Official items answered','Authored optional experience (simulated)','Applied optional experience (simulated)','Applied priorities','0.49 record kind','Parent base ID','Diagnostic intervention','Other recorded preferences','Coded features (mentions, not diagnoses)','Source JSON','Source SHA-256'],...rows.map(r=>[r.id,r.phase,r.source.classification,...keys.map(k=>r.biography[k]),...r.scores,r.interest.answered,r.authoredSkills||{},r.recordedSkills||{},r.appliedPriorities||[],r.cohort049?.kind||'',r.cohort049?.baseId||'',r.cohort049?.intervention||'',r.recordedPreferences,Object.keys(r.features),r.source.url||'Owner-only authenticated source',r.source.sha256||''])];}else{const d=cohortDistribution(rows,group);table=[['Feature group','Feature','Measure','Cohort','Count / valid scores','Selection denominator','Percent / mean score','Interpretation'],...d.features.flatMap(({definition:f,cells})=>cells.map(c=>[f.group,f.label,f.kind==='score'?'Mean /40':'Share of selected cohort',c.cohort,c.count,c.n,c.value===null?'':f.kind==='score'?c.value:c.value*100,'Fictional models; overlapping source-coded mentions are not clinical prevalence or measured skills']))];}return table.map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n';}
